public void Unlock(bool forced)
		{
			lockThreadCount_--;
			if (lockThreadCount_ <= 0 || forced)
			{
				lockThreadCount_ = 0;
				lockThread_ = null;
			}
			if (!forced)
			{
				return;
			}
			for (int i = 0; i < saveReserve_.Length; i++)
			{
				if (!saveReserve_[i])
				{
					continue;
				}
				try
				{
					saveReserve_[i] = false;
					SaveGame(i == 1, true);
				}
				catch (Exception t)
				{
					if (Config.PRINT)
					{
						Log.Info(t);
					}
				}
			}
		}

